// EnsureToken returns a valid token, bootstrapping a fresh session if needed.
// The network calls happen under the manager's lock — concurrent callers wait
// for a single in-flight handshake.
func (m *SessionManager) EnsureToken() (string, error) {
	m.mu.Lock()
	if m.token != "" {
		t := m.token
		m.mu.Unlock()
		return t, nil
	}
	m.mu.Unlock()

	// Step 1: bootstrap (optional — not every API needs a cookie seed).
	if sessionBootstrapURL != "" {
		req, err := http.NewRequest("GET", sessionBootstrapURL, nil)
		if err != nil {
			return "", fmt.Errorf("session bootstrap: %w", err)
		}
		req.Header.Set("User-Agent", sessionUserAgent)
		resp, err := m.client.Do(req)
		if err != nil {
			return "", fmt.Errorf("session bootstrap: %w", err)
		}
		_, _ = io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
	}

	// HAND-FIX(dsm-login): DSM login is a credential exchange (SYNO.API.Auth
	// form POST), not a token GET. Without credentials the request goes out with
	// no session; DSM answers code 119 and the client names the missing env vars.
	m.loginMu.Lock()
	defer m.loginMu.Unlock()
	m.mu.Lock()
	if m.token != "" { // another goroutine logged in while we waited
		t := m.token
		m.mu.Unlock()
		return t, nil
	}
	creds := m.creds
	if creds.DeviceID == "" {
		creds.DeviceID = m.deviceID
	}
	baseURL, loginErr := m.baseURL, m.loginErr
	m.mu.Unlock()
	if loginErr != nil {
		return "", loginErr
	}
	if !creds.Complete() || baseURL == "" {
		return "", nil
	}
	sess, err := dsm.Login(context.Background(), m.client, baseURL, creds)
	if err != nil {
		// A login error can echo a server-chosen value (a DSM error code, say);
		// mask every credential and session value held so far.
		return "", fmt.Errorf("%s", dsm.ScrubSecrets(err.Error(), append(m.Secrets(), creds.Password, creds.OTPCode, creds.DeviceID)...))
	}
	m.mu.Lock()
	m.token = sess.SID
	m.synoToken = sess.SynoToken
	m.issued = append(m.issued, sess.SID, sess.SynoToken, sess.DeviceID, creds.DeviceID, creds.OTPCode)
	if sess.DeviceID != "" {
		m.deviceID = sess.DeviceID
		m.creds.DeviceID = sess.DeviceID // a stale configured token is replaced
	}
	m.creds.OTPCode = "" // spent: a later relogin uses the device token
	m.mu.Unlock()
	m.saveToDisk()
	return sess.SID, nil
}

// legacySessionTokenFetch is the generated token GET, kept unreachable so a
// regeneration diff stays readable.
func (m *SessionManager) legacySessionTokenFetch() (string, error) {
	req, err := http.NewRequest("GET", sessionTokenURL, nil)
	if err != nil {
		return "", fmt.Errorf("session token fetch: %w", err)
	}
	req.Header.Set("User-Agent", sessionUserAgent)
	if sessionTokenFormat == "json" {
		req.Header.Set("Accept", "application/json")
	}
	resp, err := m.client.Do(req)
	if err != nil {
		return "", fmt.Errorf("session token fetch: %w", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("reading token response: %w", err)
	}
	if resp.StatusCode >= 400 {
		return "", fmt.Errorf("session token endpoint returned HTTP %d — IP may be rate-limited", resp.StatusCode)
	}

	var tok string
	if sessionTokenFormat == "json" {
		tok = extractJSONToken(body, sessionTokenJSONPath)
	} else {
		tok = strings.TrimSpace(string(body))
	}
	if tok == "" {
		return "", fmt.Errorf("session token endpoint returned empty body")
	}

	m.mu.Lock()
	m.token = tok
	m.mu.Unlock()
	m.saveToDisk()
	return tok, nil
}

