// ImportSession accepts cookies + a token captured from a real browser session
// (e.g. Chrome DevTools) and treats them as a live session. Used when the
// server-side handshake is rate-limited from the user's IP.
func (m *SessionManager) ImportSession(cookieDomain string, cookies []*http.Cookie, token string) error {
	if m.jar == nil {
		return fmt.Errorf("no cookie jar attached")
	}
	u, err := url.Parse(cookieDomain)
	if err != nil {
		return fmt.Errorf("invalid cookie domain: %w", err)
	}
	for _, ck := range cookies {
		if ck == nil {
			continue
		}
		target := u
		if ck.Domain != "" {
			if parsed, err := url.Parse("https://" + strings.TrimPrefix(ck.Domain, ".")); err == nil {
				target = parsed
			}
		}
		m.jar.SetCookies(target, []*http.Cookie{ck})
	}
	m.mu.Lock()
	m.token = token
	m.mu.Unlock()
	m.saveToDisk()
	return nil
}

// --- Persistence helpers ---

func (m *SessionManager) sessionFilePath() string {
	dir, err := cliutil.DataDir()
	if err != nil {
		return ""
	}
	// HAND-FIX(dsm-login): one session file per NAS, so pointing
	// SYNOLOGY_BASE_URL at another NAS never replays the first NAS's sid; the
	// name is shared with the fleet layer's trusted-device token cache.
	if u, err := url.Parse(m.baseURL); err == nil && u.Host != "" {
		return filepath.Join(dir, dsm.SessionFileName(u.Scheme+"://"+u.Host))
	}
	return filepath.Join(dir, "session.json")
}

type sessionRecord struct {
	Token string `json:"token"`
	// HAND-FIX(dsm-login): the account and origin (scheme://host:port) the sid
	// and device token belong to.
	Account   string      `json:"account,omitempty"`
	Origin    string      `json:"origin,omitempty"`
	SynoToken string      `json:"synotoken,omitempty"`
	DeviceID  string      `json:"device_id,omitempty"`
	Cookies   []jarCookie `json:"cookies"`
	Saved     time.Time   `json:"saved"`
}

type jarCookie struct {
	URL     string    `json:"url"`
	Name    string    `json:"name"`
	Value   string    `json:"value"`
	Path    string    `json:"path"`
	Expires time.Time `json:"expires,omitempty"`
}

func (m *SessionManager) loadFromDisk() {
	path := m.sessionFilePath()
	if path == "" {
		return
	}
	legacy := ""
	if m.configPath != "" && m.baseURL == "" { // HAND-FIX(dsm-login): no cross-NAS legacy fallback
		legacy = filepath.Join(filepath.Dir(m.configPath), "session.json")
	}
	data, _, err := cliutil.ReadFileWithLegacyFallback(path, legacy)
	if err != nil {
		return
	}
	var rec sessionRecord
	if err := json.Unmarshal(data, &rec); err != nil {
		return
	}
	// HAND-FIX(dsm-login): the trusted-device token outlives the session and is
	// kept per account (fleet logins share this file).
	m.mu.Lock()
	m.deviceID = dsm.CachedDeviceIDFile(path, dsm.Origin(m.baseURL), m.creds.Account)
	m.issued = append(m.issued, m.deviceID)
	m.mu.Unlock()
	if rec.Account != m.creds.Account {
		return // HAND-FIX(dsm-login): only the same account's session (an empty one included) is reused
	}
	if m.baseURL != "" && rec.Origin != m.baseURL {
		return // HAND-FIX(dsm-login): a sid from https://nas is never sent to http://nas
	}
	if time.Since(rec.Saved) > sessionTTL {
		return // stale; ignore
	}
	m.mu.Lock()
	m.token = rec.Token
	m.synoToken = rec.SynoToken
	m.issued = append(m.issued, rec.Token, rec.SynoToken)
	m.mu.Unlock()
	for _, c := range rec.Cookies {
		u, err := url.Parse(c.URL)
		if err != nil || m.jar == nil {
			continue
		}
		ck := &http.Cookie{
			Name:    c.Name,
			Value:   c.Value,
			Path:    c.Path,
			Expires: c.Expires,
		}
		m.jar.SetCookies(u, []*http.Cookie{ck})
	}
}

func (m *SessionManager) saveToDisk() {
	path := m.sessionFilePath()
	if path == "" || m.jar == nil {
		m.mu.Lock()
		m.saveErr = fmt.Errorf("no session cache location (data directory unavailable)") // HAND-FIX(dsm-login)
		m.mu.Unlock()
		return
	}
	m.mu.Lock()
	tok := m.token
	synoToken, deviceID, origin := m.synoToken, m.deviceID, m.baseURL // HAND-FIX(dsm-login)
	m.mu.Unlock()

	// Persist cookies for every host the session interacts with. cookiejar
	// strips Domain on Cookies(u), so a single-host snapshot drops cookies
	// scoped to a parent domain that other hosts in the handshake also rely
	// on. Re-snapshot per host so each destination has the cookies it needs
	// after restore.
	var cookies []jarCookie
	seen := make(map[string]bool)
	for _, host := range []string{sessionBootstrapURL, sessionTokenURL, sessionDataBaseURL} {
		if host == "" {
			continue
		}
		u, err := url.Parse(host)
		if err != nil || u.Host == "" {
			continue
		}
		rootURL := u.Scheme + "://" + u.Host + "/"
		for _, ck := range m.jar.Cookies(u) {
			key := rootURL + "|" + ck.Name + "=" + ck.Value
			if seen[key] {
				continue
			}
			seen[key] = true
			cookies = append(cookies, jarCookie{
				URL:     rootURL,
				Name:    ck.Name,
				Value:   ck.Value,
				Path:    ck.Path,
				Expires: ck.Expires,
			})
		}
	}
	rec := sessionRecord{Token: tok, Account: m.creds.Account, Origin: origin, SynoToken: synoToken, DeviceID: deviceID, Cookies: cookies, Saved: time.Now()}
	data, err := json.MarshalIndent(rec, "", "  ")
	if err != nil {
		return
	}
	_ = os.MkdirAll(filepath.Dir(path), 0o700)
	// HAND-FIX(dsm-login): keep the per-account trusted-device tokens the fleet
	// layer stores in this file; atomic write, mode 0600.
	werr := dsm.WriteSessionRecord(path, data, m.creds.Account, deviceID)
	m.mu.Lock()
	m.saveErr = werr
	m.mu.Unlock()
}

// extractJSONToken pulls a token from a JSON body by dot-separated path.
// Example: ("data.token", `{"data":{"token":"abc"}}`) → "abc". Empty string on
// parse failure or missing field.
func extractJSONToken(body []byte, path string) string {
	var obj any
	if err := json.Unmarshal(body, &obj); err != nil {
		return ""
	}
	if path == "" {
		if s, ok := obj.(string); ok {
			return s
		}
		return ""
	}
	cur := obj
	for _, part := range strings.Split(path, ".") {
		m, ok := cur.(map[string]any)
		if !ok {
			return ""
		}
		cur = m[part]
	}
	if s, ok := cur.(string); ok {
		return s
	}
	return ""
}
